root.render(<App />);

{
  "name": "Leonasc Web - Desenvolvimento de Sites",
  "description": "Portfólio de Leonardo Nascimento, especializado em sites profissionais, rápidos e sem mensalidade para pequenos negócios.",
  "requestFramePermissions": []
}

import React, { useState, useEffect, useCallback } from 'react';

// URL DA LOGO OFICIAL
const LOGO_URL = "https://i.ibb.co/sdcRqjMf/file-00000000bae0720eb4360633486b9fe7.png";

const App: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [currentSlide, setCurrentSlide] = useState(0);

  const slides = [
    {
      title: "Sua Marca com Autoridade Absoluta",
      subtitle: "Criamos ecossistemas digitais de alto impacto que posicionam seu negócio no topo do mercado.",
      buttonText: "Ver Nossos Serviços",
      link: "#servicos",
      bg: "bg-slate-900"
    },
    {
      title: "Performance Sem Mensalidades",
      subtitle: "Sites velozes, otimizados para o Google e totalmente seguros. Investimento único para resultados duradouros.",
      buttonText: "Conhecer Metodologia",
      link: "#metodologia",
      bg: "bg-blue-900"
    },
    {
      title: "Pronto Para Elevar o Nível?",
      subtitle: "Fale diretamente com Leonardo Nascimento e descubra como podemos transformar sua presença online hoje.",
      buttonText: "Chamar no WhatsApp",
      link: "https://wa.me/5516994501318",
      bg: "bg-slate-950"
    }
  ];

  const nextSlide = useCallback(() => {
    setCurrentSlide((prev) => (prev + 1) % slides.length);
  }, [slides.length]);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll);

    const timer = setInterval(nextSlide, 6000); // Transição suave de 6 segundos

    return () => {
      window.removeEventListener('scroll', handleScroll);
      clearInterval(timer);
    };
  }, [nextSlide]);

  const scrollToSection = (e: React.MouseEvent<HTMLAnchorElement>, id: string) => {
    if (id.startsWith('http')) return; // Permite links externos como WhatsApp
    e.preventDefault();
    const element = document.getElementById(id);
    if (element) {
      const offset = isScrolled ? 80 : 250;
      const bodyRect = document.body.getBoundingClientRect().top;
      const elementRect = element.getBoundingClientRect().top;
      const elementPosition = elementRect - bodyRect;
      const offsetPosition = elementPosition - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
    }
    setMobileMenuOpen(false);
  };

  return (
    <div className="min-h-screen bg-[#ffffff] font-['Inter'] selection:bg-blue-600 selection:text-white overflow-x-hidden">

      {/* HEADER ESCURO SÓLIDO - FOCO NA LOGO */}
      <header className={`fixed w-full z-50 transition-all duration-500 ease-in-out bg-slate-950 ${
        isScrolled 
        ? 'py-3 shadow-2xl border-b border-white/10' 
        : 'py-10 md:py-14 border-b border-white/5'
      }`}>
        <div className="max-w-[1200px] mx-auto px-6 flex flex-col items-center">

          {/* Logo Principal */}
          <a 
            href="#inicio" 
            onClick={(e) => scrollToSection(e, 'inicio')} 
            className={`transition-all duration-500 transform hover:scale-[1.02] active:scale-95 ${
              isScrolled ? 'h-10 md:h-12' : 'h-28 md:h-[160px]'
            }`}
          >
            <img 
              src={LOGO_URL} 
              alt="Leonasc Web" 
              className="h-full w-auto object-contain"
            />
          </a>

          {/* Menu de Navegação - Abaixo da Logo */}
          <nav className={`mt-8 transition-all duration-500 ${
            isScrolled ? 'h-0 opacity-0 pointer-events-none mt-0 overflow-hidden' : 'h-auto opacity-100'
          } hidden lg:block`}>
            <div className="flex items-center space-x-10 text-[11px] font-bold text-white uppercase tracking-[0.3em]">
              <a href="#servicos" onClick={(e) => scrollToSection(e, 'servicos')} className="hover:text-blue-400 transition-colors">
                Serviços
              </a>
              <a href="#portfolio" onClick={(e) => scrollToSection(e, 'portfolio')} className="hover:text-blue-400 transition-colors">
                Portfólio
              </a>
              <a href="#metodologia" onClick={(e) => scrollToSection(e, 'metodologia')} className="hover:text-blue-400 transition-colors">
                Metodologia
              </a>
              <a href="#contato" onClick={(e) => scrollToSection(e, 'contato')} className="bg-blue-600 px-6 py-2 rounded-lg hover:bg-blue-500 transition-all">
                Contato
              </a>
            </div>
          </nav>

          {/* Mobile Menu Trigger */}
          <button 
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)} 
            className="lg:hidden absolute right-6 top-1/2 -translate-y-1/2 text-white"
          >
            <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={mobileMenuOpen ? "M6 18L18 6" : "M4 6h16M4 12h16M4 18h16"} />
            </svg>
          </button>
        </div>
      </header>

      {/* Mobile Menu */}
      {mobileMenuOpen && (
        <div className="fixed inset-0 z-[60] bg-slate-950 flex flex-col items-center justify-center space-y-8 animate-in fade-in duration-300">
          <img src={LOGO_URL} className="h-24 w-auto mb-6" alt="Logo" />
          <div className="text-xl font-bold text-white flex flex-col items-center space-y-6 uppercase tracking-widest">
            <a href="#servicos" onClick={(e) => scrollToSection(e, 'servicos')}>Serviços</a>
            <a href="#portfolio" onClick={(e) => scrollToSection(e, 'portfolio')}>Portfólio</a>
            <a href="#contato" onClick={(e) => scrollToSection(e, 'contato')}>Contato</a>
          </div>
          <button onClick={() => setMobileMenuOpen(false)} className="px-8 py-3 bg-white/10 rounded-full text-white font-bold text-xs tracking-widest uppercase">
            Fechar Menu
          </button>
        </div>
      )}

      {/* SLIDER / CARROSSEL PREMIUM - ABAIXO DO HEADER */}
      <section id="inicio" className="relative w-full h-[600px] md:h-[800px] overflow-hidden bg-slate-950">
        <div className="absolute inset-0 z-0">
          {slides.map((slide, index) => (
            <div
              key={index}
              className={`absolute inset-0 transition-opacity duration-1000 ease-in-out flex items-center justify-center p-6 ${
                index === currentSlide ? 'opacity-100 z-10' : 'opacity-0 z-0'
              } ${slide.bg}`}
            >
              {/* Overlay suave para textura */}
              <div className="absolute inset-0 bg-gradient-to-b from-black/40 to-transparent opacity-50"></div>

              <div className="relative z-10 max-w-[900px] text-center pt-40 md:pt-64">
                <span className="inline-block px-4 py-1 mb-6 border border-white/20 rounded-full text-[10px] font-black tracking-[0.4em] uppercase text-white/60">
                  Leonardo Nascimento • Leonasc Web
