                <p className="text-lg md:text-xl text-white/80 mb-12 leading-relaxed max-w-2xl mx-auto font-medium animate-in fade-in duration-1000 delay-300">
                  {slide.subtitle}
                </p>
                <div className="animate-in fade-in slide-in-from-bottom-4 duration-700 delay-500">
                  <a 
                    href={slide.link} 
                    onClick={(e) => scrollToSection(e, slide.link.replace('#', ''))}
                    target={slide.link.startsWith('http') ? '_blank' : '_self'}
                    className="inline-block px-12 py-5 bg-white text-slate-950 rounded-xl font-black text-lg hover:bg-blue-600 hover:text-white transition-all shadow-2xl"
                  >
                    {slide.buttonText}
                  </a>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Indicadores do Slider */}
        <div className="absolute bottom-12 left-1/2 -translate-x-1/2 z-20 flex gap-4">
          {slides.map((_, index) => (
            <button
              key={index}
              onClick={() => setCurrentSlide(index)}
              className={`h-1.5 transition-all duration-500 rounded-full ${
                index === currentSlide ? 'w-12 bg-blue-500' : 'w-4 bg-white/20'
