// Hook para animação de revelação ao rolar
const useScrollReveal = () => {
  const [isVisible, setIsVisible] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, []);

  return { ref, isVisible };
};

const Reveal: React.FC<{ children: React.ReactNode, delay?: number, direction?: 'up' | 'down' | 'none' }> = ({ children, delay = 0, direction = 'up' }) => {
  const { ref, isVisible } = useScrollReveal();

  const getTransform = () => {
    if (!isVisible) {
      if (direction === 'up') return 'translate-y-12 scale-95';
      if (direction === 'down') return '-translate-y-12 scale-95';
      return 'scale-95';
    }
    return 'translate-y-0 scale-100';
  };

  return (
    <div 
      ref={ref} 
      className={`transition-all duration-[1200ms] cubic-bezier(0.23, 1, 0.32, 1) transform ${
        isVisible ? 'opacity-100' : 'opacity-0'
      } ${getTransform()}`}
      style={{ transitionDelay: `${delay}ms` }}
    >
      {children}
    </div>
  );
};

