// Hook para Tilt 3D em elementos
const useTilt = () => {
  const ref = useRef<HTMLDivElement>(null);
  const [style, setStyle] = useState({});

  const onMouseMove = (e: MouseEvent) => {
    if (!ref.current) return;
    const { left, top, width, height } = ref.current.getBoundingClientRect();
    const x = (e.clientX - left) / width;
    const y = (e.clientY - top) / height;
    const move = 15;
    const xDeg = (y - 0.5) * move;
    const yDeg = (x - 0.5) * -move;
    setStyle({
      transform: `perspective(1000px) rotateX(${xDeg}deg) rotateY(${yDeg}deg) scale3d(1.02, 1.02, 1.02)`,
      transition: 'none'
    });
  };

  const onMouseLeave = () => {
    setStyle({
      transform: `perspective(1000px) rotateX(0deg) rotateY(0deg) scale3d(1, 1, 1)`,
      transition: 'all 0.5s ease'
    });
  };

  useEffect(() => {
    const el = ref.current;
    if (el) {
      el.addEventListener('mousemove', onMouseMove as any);
      el.addEventListener('mouseleave', onMouseLeave);
    }
    return () => {
      if (el) {
        el.removeEventListener('mousemove', onMouseMove as any);
        el.removeEventListener('mouseleave', onMouseLeave);
      }
    };
  }, []);

  return { ref, style };
};

// Hook para Revelação Progressiva (Scroll Reveal)
const Reveal: React.FC<{ children: React.ReactNode, delay?: number, width?: string }> = ({ children, delay = 0, width = "fit-content" }) => {
  const ref = useRef(null);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) setIsVisible(true);
    }, { threshold: 0.1 });
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, []);

  return (
    <div ref={ref} style={{ width, position: 'relative', overflow: 'hidden' }}>
      <div
        className={`transition-all duration-[1500ms] cubic-bezier(0.77, 0, 0.175, 1)`}
        style={{
          transform: isVisible ? 'translateY(0)' : 'translateY(100%)',
          opacity: isVisible ? 1 : 0,
          transitionDelay: `${delay}ms`
        }}
      >
        {children}
      </div>
    </div>
  );
};

